head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/elw_recv_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용

scwin.vScrenID = "ULDSTF05900.xml";
scwin.clickBzProcsNo = "";
scwin.readOnlyYn = "N";
scwin.procJob = "";
scwin.logicPackYn = "Y";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_set_code = function() {
    dts_ElwInst.DataID = "/CodeAction.do?method=listWrntCd&For=R";
    dts_ElwInst.Reset();
    //alert("call");

};



/**
 * 추가상장신청시의 업무구분코드 가져오기
 */
scwin.fn_getListBzTpCd = function(str) {
    var val = '';
    if (str == LIST_BZ_TP_CD_002) {
        val = LIST_BZ_TP_CD_004;
    } else if (str == LIST_BZ_TP_CD_003) {
        val = LIST_BZ_TP_CD_005;
    }
    return val;
};
scwin.fn_list_sync = function() {
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        var url = "/ElwListedReceive.do?method=listElwUnreceiveRequest&inputMessageId=ELW_UNRECV_LSTRCV_INOUT";
        url += "&ISUR_CD=" + $c.stf.getObjectValue(cmb_ISUR_CD);
        url += "&LIST_BZ_TP_CD=" + $c.stf.getObjectValue(cmb_LIST_BZ_TP_CD);
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_List_1.DataID = encodeURI(url);
        dts_List_1.Reset();
        $c.cm.ShowWin(grd_List_1);
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        var url = "/ElwListedReceive.do?method=listElwAddUnreceiveRequest&inputMessageId=ELW_UNRECV_LSTRCV_INOUT";
        url += "&ISUR_CD=" + $c.stf.getObjectValue(cmb_ISUR_CD);
        url += "&LIST_BZ_TP_CD=" + scwin.fn_getListBzTpCd($c.stf.getObjectValue(cmb_LIST_BZ_TP_CD));
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_List_2.DataID = encodeURI(url);
        dts_List_2.Reset();
        $c.cm.ShowWin(grd_List_2);
    }
};
scwin.fn_setBzProcsNo = function(obj, dtsObj) {
    scwin.clickBzProcsNo = dtsObj.getCellData(eval(obj), "BZ_PROCS_NO");
    //alert("fn_setBzProcsNo():"+clickBzProcsNo);

};
scwin.fn_OpenDetail = function(row, dtsObj) {
    scwin.fn_setBzProcsNo(row, dtsObj);
    var vbzTpCd = dtsObj.getCellData(row, "LIST_BZ_TP_CD");
    $c.elw.fn_OpenDetailRecv(vbzTpCd);
};
scwin.fn_getDataSet = function() {
    var dtsObj;
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        dtsObj = dts_List_1;
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        dtsObj = dts_List_2;
    }
    return dtsObj;
};
scwin.fn_selectIsuCheckCnt = function(dtsObj) {
    var k = 0;
    for (var i = 1; i <= dtsObj.getTotalRow(); i++) {
        if (dtsObj.getCellData(i, "CHECK") == "T") {
            k++;
        }
    }
    return k;
};
scwin.fn_CheckForm = function(procTyp) {
    if (procTyp == "2") {
        // jackal_12.08.01 반송구분추가 체크
        if ($c.stf.getObjectValue(cmb_RETN_BZ_TP_CD) == "") {
            $c.win.alert("[반송구분]를 선택하세요.");
            cmb_RETN_BZ_TP_CD.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txb_RET_RSN) == "") {
            $c.win.alert("[반송사유]를 입력하세요.");
            txb_RET_RSN.focus();
            return false;
        }
    } else {
        // jackal_12.08.01 반송구분추가 체크
        if ($c.stf.getObjectValue(cmb_RETN_BZ_TP_CD) != "") {
            $c.win.alert("반송시에만 [반송구분]를 선택하세요.");
            cmb_RETN_BZ_TP_CD.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txb_RET_RSN) != "") {
            $c.win.alert("반송시에만 [반송사유]를 입력하세요.");
            txb_RET_RSN.focus();
            return false;
        }
    }
    return true;
};
scwin.fn_packacpt = function() {
    var dtsObj = scwin.fn_getDataSet();
    var vSelectCnt = scwin.fn_selectIsuCheckCnt(dtsObj);
    if (vSelectCnt == 0) {
        $c.win.alert("[종목]을 선택하세요.");
        return;
    }
    if (!scwin.fn_CheckForm("1")) {
        return;
    }
    scwin.procJob = ' 선택한 ' + vSelectCnt + '종목에대한 일괄접수처리 ';
    var res = window.confirm($c.stf.getMessageParam('MSG-A006', scwin.procJob));
    if (res) {
        //dts_Isu.UserStatus(1) = TB_JOB_UPDATE;
        for (var i = 1; i <= dtsObj.getTotalRow(); i++) {
            if (dtsObj.getCellData(i, "CHECK") == "T") {
                dtsObj.setCellData(i, "LIST_PROCS_STAT_CD", ELW_RECV_PROC_CD_10);
            }
        }

        //alert('[dtsObj]'+dtsObj.text);
        trs_Save.Action = $c.lc.fn_encodeNSession("/ElwListedReceive.do?method=receiveElw&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03);
        trs_Save.KeyName = "toinb_dataid4";
        if (MaxTab_01.getSelectedTabIndex() == 1) {
            trs_Save.KeyValue = "JSP(I:pInput=dts_List_1)";
        } else if (MaxTab_01.getSelectedTabIndex() == 2) {
            trs_Save.KeyValue = "JSP(I:pInput=dts_List_2)";
        }
        trs_Save.Post();
    }
};
scwin.fn_packret = function() {
    var dtsObj = scwin.fn_getDataSet();
    var vSelectCnt = scwin.fn_selectIsuCheckCnt(dtsObj);
    if (vSelectCnt == 0) {
        $c.win.alert("[종목]을 선택하세요.");
        return;
    }
    if (!scwin.fn_CheckForm("2")) {
        return;
    }
    scwin.procJob = ' 선택한 ' + vSelectCnt + '종목에대한 일괄반송처리 ';
    var res = window.confirm($c.stf.getMessageParam('MSG-A006', scwin.procJob));
    if (res) {
        //dts_Isu.UserStatus(1) = TB_JOB_UPDATE;
        for (var i = 1; i <= dtsObj.getTotalRow(); i++) {
            if (dtsObj.getCellData(i, "CHECK") == "T") {
                dtsObj.setCellData(i, "LIST_PROCS_STAT_CD", ELW_RECV_PROC_CD_02);
                dtsObj.setCellData(i, "RET_RSN", $c.stf.getObjectValue(cmb_RETN_BZ_TP_CD) + ":" + $c.stf.getObjectValue(txb_RET_RSN));
            }
        }

        //alert('[dtsObj]'+dtsObj.text);
        trs_Save.Action = $c.lc.fn_encodeNSession("/ElwListedReceive.do?method=receiveElw&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03);
        trs_Save.KeyName = "toinb_dataid4";
        if (MaxTab_01.getSelectedTabIndex() == 1) {
            trs_Save.KeyValue = "JSP(I:pInput=dts_List_1)";
        } else if (MaxTab_01.getSelectedTabIndex() == 2) {
            trs_Save.KeyValue = "JSP(I:pInput=dts_List_2)";
        }
        trs_Save.Post();
        $c.stf.setObjectValue(txb_RET_RSN, ""); //초기화

    }
};



/********************************************** 
 * 함수명   : fn_ExcelDown()
 * 설명       : 정보를 excel로 다운 받는다.
 ***********************************************/
scwin.fn_ExcelDown = function() {
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        $c.data.downloadGridViewExcel(grd_List_1, "신규상장접수목록", "", "8");
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        $c.data.downloadGridViewExcel(grd_List_2, "추가상장접수목록", "", "8");
    }
};
scwin.btn_LgcChk_onclick = function() {
    var dtsObj = scwin.fn_getDataSet();
    if (scwin.fn_selectIsuCheckCnt(dtsObj) == 0) {
        $c.win.alert("[종목]을 선택하세요.");
        return;
    } else {
        $c.elw.fn_OpenLogicCheck();
    }
};
scwin.btn_RcvPrc_onclick = function() {
    if (js_svrGubun == 'dr') {
        $c.win.alert("DR에서 운영될때는 서비스가 제공되지 않습니다.");
        return;
    }
    scwin.fn_packacpt();
};
scwin.btn_RetPrc_onclick = function() {
    scwin.fn_packret();
};
scwin.cmb_ISUR_CD_OnSelChange = function() {
    scwin.fn_list_sync();
};
scwin.cmb_LIST_BZ_TP_CD_OnSelChange = function() {
    scwin.fn_list_sync();
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    scwin.fn_ExcelDown();
};
scwin.dts_List_1_OnLoadError = function() {
    $c.stf.alert_error(dts_List_1);
};
scwin.dts_List_2_OnLoadError = function() {
    $c.stf.alert_error(dts_List_2);
};
scwin.grd_List_1_OnHeadCheckClick = function(col, colid, bCheck) {
    //alert('grd_List.OnHeadCheckClick('+col+','+ colid+','+ bCheck+')');
    $c.elw.fn_setCheckBox(grd_List_1, dts_List_1, bCheck);
};
scwin.grd_List_2_OnHeadCheckClick = function(col, colid, bCheck) {
    $c.elw.fn_setCheckBox(grd_List_2, dts_List_2, bCheck);
};
scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_1);
};
scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_2);
};
scwin.grd_List_1_OnDblClick = function(row, colid) {
    if (colid == 'ISU_KOR_ABBRV') {
        scwin.fn_OpenDetail(row, dts_List_1);
    }
};
scwin.grd_List_2_OnDblClick = function(row, colid) {
    if (colid == 'ISU_KOR_ABBRV') {
        scwin.fn_OpenDetail(row, dts_List_2);
    }
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", scwin.procJob));
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001", scwin.procJob));
    scwin.fn_list_sync();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.MaxTab_01_OnSelChanged = function(nIndex) {
    scwin.fn_list_sync();
};
scwin.gform_onload = function() {
    MaxTab_01.setSelectedTabIndex(1);
    scwin.fn_set_code();
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.fn_list_sync();
};
scwin.grd_List_1_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.grd_List_2_CanColumnPosChange = function(row, colid) {
    return true;
};
